import { asString, useSearchParam } from '../../url/useSearchParam';
import { GRADES, gradeOn, type Person } from '../people/usePeople';
import { STATUSES } from '../people/useSheetFigures';
import { usePeriodDueTotal } from '../periods/usePeriodDueTotal';
import { usePeriods } from '../periods/usePeriods';
import { formatCents } from '../rates/due';
import { useVoidReasons } from '../voidreasons/useVoidReasons';

// The sheet at a glance, worked from the same figures the lists show. Per grade: how many people
// are on it today (retired people left out), their due-totals added up (skipping n/a) and how many
// of them are active. Per period: its due-total, as the period list shows it, and its change from
// the period before it by start date (blank for the earliest). Per status: how many claims have it.
// Per reason on the sheet's void list: how many VOID claims were voided with it.
export function SummaryPanel({
  people,
  today,
  totalOf,
  isActive,
  statusCount,
  voidReasonCount,
}: {
  people: Person[];
  today: string | undefined;
  totalOf: (person: Person) => bigint | null;
  isActive: (person: Person) => boolean;
  statusCount: (status: (typeof STATUSES)[number]) => number;
  voidReasonCount: (reason: string) => number;
}) {
  const [sheet] = useSearchParam('sheet', asString);
  const periods = usePeriods(sheet);
  const periodDueTotal = usePeriodDueTotal(sheet);
  const voidReasons = useVoidReasons(sheet);
  const current = people.filter((p) => !p.retired);
  const byStart = [...periods].sort((a, b) => a.from.localeCompare(b.from));
  const changeOf = (p: (typeof periods)[number]) => {
    const i = byStart.indexOf(p);
    return i <= 0 ? '' : formatCents(periodDueTotal(p) - periodDueTotal(byStart[i - 1]));
  };
  return (
    <section data-testid="summary">
      <h3>Summary</h3>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = current.filter((p) => gradeOn(p, today) === g);
            const due = onGrade.reduce((sum, p) => sum + (totalOf(p) ?? 0n), 0n);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{formatCents(due)}</td>
                <td data-testid={`summary-grade-${g}-active`}>{onGrade.filter(isActive).length}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{formatCents(periodDueTotal(p))}</td>
              <td data-testid={`summary-period-${p.name}-change`}>{changeOf(p)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{statusCount(s)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map((r) => (
            <tr key={r}>
              <td>{r}</td>
              <td data-testid={`summary-void-${r}-count`}>{voidReasonCount(r)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
import { countsAtEnd, useClaims } from '../claims/useClaims';
import { gradeOn, heldOn, retiredOn, usePeople } from '../people/usePeople';
import { claimDue, toCents } from '../rates/due';
import { useGrace } from '../claims/useGrace';
import { rateOn, useRates } from '../rates/useRates';
import { useFloor, useLatePct, usePolicy } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { periodOf, usePeriods, type Period } from './usePeriods';

/** A person's due-total for a period: the dues as shown now, late charges included, of their claims whose due-by
 *  (as fixed at creation) falls in it that counted at the end of its last day (see countsAtEnd), leaving out their unbound OPEN claims dated within one of their holds, or all of them once they are retired (a claim whose due is n/a
 *  adds nothing); a closed or soft-closed period gives the figure fixed when it was closed (0.00 for a person added later). */
export function usePersonPeriodDueTotal(sheet: string): (period: Period, personId: string) => bigint {
  const periods = usePeriods(sheet);
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const floor = useFloor(sheet);
  const late = { pct: useLatePct(sheet), today: useSheetToday(sheet), grace: useGrace(sheet) };
  const policy = usePolicy(sheet);
  const personOf = new Map(people.map((p) => [p.id, p]));
  return (period: Period, personId: string) => {
    if (period.closed || period.softClosed) return toCents(period.closedPersonTotals[personId] ?? '0.00');
    const person = personOf.get(personId);
    if (!person) return 0n;
    return claims
      .filter((c) => c.personId === personId && countsAtEnd(c, period.to, (date) => heldOn(person, date) || retiredOn(person, late.today), late.today) && periodOf(periods, c.dueBy)?.name === period.name)
      .reduce((sum, c) => sum + (claimDue(c, rateOn(rates, gradeOn(person, c.date), c.date), floor, late, policy) ?? 0n), 0n);
  };
}

/** A period's due-total: the sum of every person's due-total for it. */
export function usePeriodDueTotal(sheet: string): (period: Period) => bigint {
  const people = usePeople(sheet);
  const personDueTotal = usePersonPeriodDueTotal(sheet);
  return (period: Period) => people.reduce((sum, p) => sum + personDueTotal(period, p.id), 0n);
}
